import{_ as r}from"./chunks/0791faeba260662f5fb5.BRjgzJfR.js";import{_ as a,C as o,o as l,c as h,j as e,a as i,E as n,a5 as s}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"自我架构的艺术（如何改变你是谁）","description":"","frontmatter":{"title":"自我架构的艺术（如何改变你是谁）","originalTitle":"The Art Of Self-Architecture (How To Change Who You Are)","date":"2023-05-06","originalUrl":"https://thedankoe.com/letters/the-art-of-self-architecture-how-to-change-who-you-are/","minutes":8,"sourceHash":"a7ead0efa4f7fb42e8abe4148dce4e4b64c19b9025945214df2a7e62fa26fbcf","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-art-of-self-architecture-how-to-change-who-you-are/"}]]},"headers":[],"relativePath":"letters/the-art-of-self-architecture-how-to-change-who-you-are.md","filePath":"letters/the-art-of-self-architecture-how-to-change-who-you-are.md"}'),c={name:"letters/the-art-of-self-architecture-how-to-change-who-you-are.md"};function f(u,p,d,m,g,_){const t=o("ArticleMeta");return l(),h("div",null,[p[0]||(p[0]=e("h1",{id:"自我架构的艺术-如何改变你是谁",tabindex:"-1"},[i("自我架构的艺术（如何改变你是谁） "),e("a",{class:"header-anchor",href:"#自我架构的艺术-如何改变你是谁","aria-label":'Permalink to "自我架构的艺术（如何改变你是谁）"'},"​")],-1)),n(t),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/ZdtU6TKD1qo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>生活是一场游戏，而你的角色决定了结局。</p><p>你的角色是具有可塑性的。</p><p>这是你必须建立的第一个认知。</p><p>你是可以改变的。</p><p>无论这有多痛苦。</p><p>无论你的大脑告诉你什么。</p><p>无论你有多想紧紧抓住当前生活的舒适区，哪怕这种舒适所造成的破坏其实远超你的想象。</p><p>你的角色就是你的自我概念：你认为自己是谁。</p><p>它是你处理过的想法、信念、经验和信息的混合体，构成了你与现实互动的操作系统。</p><p>对大多数人来说，他们的角色是被别人设定的。</p><p>在童年时期，我们每一个人都是环境的产物。</p><p>人类学习的本能驱力让我们吸收任何有助于生存的信息。</p><p>带着这些信息，我们被设定在了一条默认却平庸的轨迹上。</p><p>就像一列在铁轨上呼啸向前的火车，如果我们不学会主导自己的冒险，我们可能最终会驶向死胡同。</p><p>人类的命运并不是绝对有保障的。</p><p>任何生命形式都是如此。</p><p>如果我们不做出明智且有意识的选择，我们可能会将自己从地球上抹去。</p><p>这是最坏的情况，但其可能性却在不断增加。</p><p>我们的角色决定我们的行动。</p><p>我们的行动促成了社会与文化。</p><p>社会与文化又影响了其他角色的编程。</p><p>构成我们角色形态的想法、信念和信息，将通过我们的选择传播出去，从而塑造其他的角色。</p><p>集体的角色将决定其自身的命运。</p><p>这一切都始于个体的能力：从平庸的轨迹中醒来，改变他们自己，并让他们的行动去影响世界。</p><h2 id="个人发展的悖论" tabindex="-1">个人发展的悖论 <a class="header-anchor" href="#个人发展的悖论" aria-label="Permalink to &quot;个人发展的悖论&quot;">​</a></h2><p>生活是一场包容了无数无限游戏的游戏。</p><p>有两个宏观游戏是最能带来丰硕成果的：</p><p><strong>1) 外部游戏</strong></p><p>外部游戏是你选择如何度过你的一生。</p><p>它是你所追求的、能够影响人类的自发目标。</p><p>它是你一生的事业（也就是我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中帮助你发现并创造的东西）。</p><p>它是你投入时间、注意力和金钱去构建的、作为创造价值方式的事物。</p><p><strong>2) 内部游戏</strong></p><p>如果你的外部追求没有以哲学意义上的精通作为支撑，它们将依然是肤浅且毫无意义的。</p><p>对于每一个你向外追求的目标，都有一个你必须向内解锁的课题。</p><p>这就是个人发展的悖论。</p><p>你在世界上攀登得越高，你就越需要深入探索自己的内心……前提是你没有迷失方向。</p><p>随着你的自我发展，你会提升你的心智层级。</p><p>在每一个层级，你都能以上帝视角俯瞰自己过去的经历。</p><p>你开始意识到你曾经在玩（或者任由它玩弄你）的那个系统或游戏的结构。</p><p>经历一段内心的挣扎，是达到下一个心智层级的必经之路。</p><p>当你获得了必需的技能或知识，你就会达到下一个心智层级，从而解决你曾面临的问题。</p><p>就像我曾经搞砸了7门不同的生意。</p><p>我尝试了天底下所有能试的东西。</p><p>学习了我能学的所有技能。</p><p>尝试过自由职业、代发货、做代运营以及社交媒体，但收效甚微。</p><p>起初毫无起色，随后一切水到渠成。</p><p>突然之间，我一直收集的拼图碎片在我的大脑中拼合在了一起。</p><p>一场名为“顿悟”的雪崩猛然闯入了我的精神世界。</p><p>我确切地知道了该怎么做，才能让我的下一次商业尝试取得成功。</p><p>在经历了这种现象的多次循环之后，我才有了今天的成就。</p><p>这就是为什么无论我免费教给你多少“玩法”，你依然需要挣扎好几年。</p><p>你必须与现实去搏斗，才能获得那个对你来说完美契合的教训。</p><p>它不会在一瞬间发生。你必须终生致力于这条充满不确定性的道路。</p><h2 id="从肤浅到形而上-向内雕刻" tabindex="-1">从肤浅到形而上（向内雕刻） <a class="header-anchor" href="#从肤浅到形而上-向内雕刻" aria-label="Permalink to &quot;从肤浅到形而上（向内雕刻）&quot;">​</a></h2><blockquote><p>解决问题者或价值创造者的道路，是你逃离可替代性世界的方法。爱上问题带来的挑战，从肤浅的到形而上的，你理想的未来就会自行创造出来。这就是无限游戏。</p></blockquote><p>这是摘自我终于写完的新书《专注的艺术》（<em>The Art Of Focus</em>）里的一段话，（希望）能在今年出版。</p><p>要改变你是谁，你必须在平静与进步之间找到平衡。</p><p>你必须向外推进，追求有意义的目标，同时褪去你已经形成的坚硬的身份外壳。</p><p>特定的目标需要特定的角色才能实现。</p><p>如果你的外部旅程中忽视了内部的修炼，你最终将被困在一种表层的生活状态中：</p><p>一个没有健康的商人。</p><p>一个没有哲学的健美运动员。</p><p>一个没有价值观的搭讪达人（PUA）。</p><p>自我架构的艺术要求全面整体的发展。</p><p>当你在实现更大更好的目标时，新的问题会浮现在你的意识中，但大多数人都忽视了这些，这也导致了目前的社会现状。</p><p>过去我们已经多次讨论过如何设定、追求并实现有意义的目标（<a href="https://thedankoe.com/the-focus-formula-how-to-take-control-of-your-life/" target="_blank" rel="noreferrer">比如这封信</a>），因此我们将把重点放在向内雕刻上。</p><p><img src="'+r+'" alt=""></p><p>把你究竟是谁、你的自我概念，看作是你随着时间推移建立起来的一种智性结构。</p><p>当你改造一栋房子时，你会直接动地基吗？</p><p>还是从微小的外观问题开始，这样整栋房子才不会轰然倒塌？</p><p>当你开始雕凿一块大理石时，你会用尽全力挥舞锤子猛砸吗？</p><p>还是你会进行微小、精准的敲击，以免把它砸成粉末？</p><p>同样的概念也适用于改变你自己。</p><p>大多数人想从深层的、精神层面的以及位于他们核心的形而上学问题开始着手。</p><p>如果你甚至连最基本的自我提升工作都没做过，比如：</p><ul><li>去健身房或锻炼</li><li>改善你的营养状况和生活习惯</li><li>获取高价值的技能和知识</li></ul><p>那你肯定要倒大霉了。</p><p>我敢说，那些不去做表面工作却试图变得“有精神追求”的人，这么做恰恰是出于肤浅的原因。</p><p>他们把灵性当作一张高尚卡，以此来逃避通过追求目标为人类做出任何形式的贡献。</p><h2 id="挑战-技能-目标-利润" tabindex="-1">挑战:技能 = 目标:利润 <a class="header-anchor" href="#挑战-技能-目标-利润" aria-label="Permalink to &quot;挑战:技能 = 目标:利润&quot;">​</a></h2><blockquote><p>当一个人应对某种情境的挑战需要运用其所有相关技能时，他的注意力就会完全被这项活动所吸引。没有多余的心理能量可以用来处理该活动提供的信息之外的任何事情。所有的注意力都集中在相关的刺激上。——米哈里·契克森米哈赖</p></blockquote><p>这就是通往享受极致生活的路径。</p><p>以下是你需要遵循的步骤：</p><p><strong>1) 追求一个足够有挑战性的目标</strong></p><p>从小处和肤浅的地方开始。</p><p>修复你的健康、财务和心态。</p><p>将一只脚踏入未知领域，这样你就能感受到迫使你采取行动所需的压力。</p><p>这会给你一个较小的目标去自我实现。</p><p><strong>2) 获取实现目标所需的技能</strong></p><p>认为在没有自我教育的情况下就能实现自发的目标，这种想法很愚蠢。</p><p>你需要让你的意识沉浸在那些能为你设定新身份（并为你提供攻克目标的知识）的信息中。</p><p>关注那些提供与你目标相关的具体信息的社交媒体账号。</p><p>买上1到3本相关的书，并狼吞虎咽地读完它们。</p><p>当你把一个目标放在首位时，你就会开始带着意图去感知周围的情况。</p><p>意图 = 你正在努力够向的地方。</p><p>信息将变得与你的生活更加相关且适用。</p><p>你终结了盲目分心和消费的循环。</p><p>如果你不知道该学什么技能，可以考虑学习<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">高影响力写作</a>。这可以说是数字时代最赚钱的技能。我和我的学生都已经证明了这一点。</p><p><strong>3) 寻找并叠加你的“为什么”，以培养个人哲学</strong></p><p>如果你难于付诸行动，那是因为你没有一个<em>有说服力的、个人的且内在的</em>行动理由。</p><p>第一步很困难，但你必须迈出这一步。</p><p>然后，在体验生活的过程中，留心收集各种理由。</p><p>我以前讨厌散步。</p><p>我看不出这有什么“意义”。</p><p>有一天，我决定减点肥。</p><p>我觉得自己的体重已经超出我能接受的范围了，于是我的脑海中形成了一个目标。</p><p>我开始消费相关信息，拼凑出了一套减肥策略。</p><p>散步似乎是增加能量消耗的一个绝佳方式。</p><p>于是，我开始了每天走10,000步。</p><p>在那些散步的过程中，我意识到：</p><ul><li>我可以听讲座和有声书来充实我的大脑</li><li>我可以产生灵感并撰写内容</li><li>我其实很享受走出门休息片刻，这有助于我集中注意力</li><li>减重后，我的日常活动量更高了，所以我可以吃得更多（血赚）同时还保持苗条</li><li>我可以在路上接听业务电话</li><li>我一年中大部分时间都能保持不错的古铜色肌肤</li></ul><p>现在，我每天至少走20,000步。</p><p>无聊的时候，我会去散步。</p><p>缺乏创造力的时候，我会去散步。</p><p>需要去商店的时候，我会步行去。</p><p>最后一点甚至影响了我选择居住的地方。</p><p>正是因为它给我带来的好处，我想我永远不会住在一个不适合步行的城市。</p><p>这不仅适用于散步，也适用于融入我生活方式的每一个习惯。</p><p>如果你不知道自己“为什么”在做某事，那你为什么还要去做呢？这是盲目的第一个迹象。</p><p>去追求目标。</p><p>为每一个目标发展出一套内在的哲学。</p><p>慢慢培养那些能铸就你是谁的习惯（因为你的选择决定了一切）。</p><p><strong>4) 将你的追求转化为有价值的贡献</strong></p><p>我们生活在这样一个时代：你可以在互联网这个无限的公共论坛上分享你的知识，并通过提升自己来获得报酬。</p><p>无论如何，那是最好、最成功的商业模式。</p><p>那就是解决真实的、有意义的、能改变生活的问题的模式。</p><p>大多数企业之所以失败，是因为他们试图解决的问题并不真实。</p><p>通过解决你自己的问题，你就知道它们是真实的。</p><p>你知道解决这些问题改变了你的人生。</p><p>现在，你需要做的就是进行自我反思，创造一个别人可以效仿的流程，并把它提供给别人（然后给它贴上价签）。</p><p>这就是你将目标转化为利润的方式。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/the-art-of-self-architecture-how-to-change-who-you-are">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',136))])}const A=a(c,[["render",f]]);export{w as __pageData,A as default};
